// Structured review evidence; the report renderer keeps IDs and counts consistent.
export const findings=[];
const known='node review/gpt-6.1-sol/repro/known-backend.mjs';
const faults='node review/gpt-6.1-sol/repro/server-faults.mjs';
const browser='node node_modules/@playwright/test/cli.js test -c review/gpt-6.1-sol/repro/playwright.config.ts';
const policy='node review/gpt-6.1-sol/repro/absence-and-config.mjs';
function add(title,severity,category,current,fixType,where,related,excerpt,what,impact,root,fix,test,accept,risk,reproduce,probe=null){
 findings.push({id:`SOL-${String(findings.length+1).padStart(3,'0')}`,title,severity,category,current,fixType,where,related,excerpt,what,impact,root,fix,test,accept,risk,reproduce,confidence:probe?`CONFIRMED (repro: \`review/gpt-6.1-sol/repro/${probe}\`)`:'LIKELY (code evidence, not executed; deployed controls outside this repository are unverified)'});
}
add('Cash-outs are discarded even when no recipient is credited','S0','MONEY','Play chips can be lost when the recipient row is missing or no longer HUMAN.','CODE-NOW','apps/server/src/game/manager.ts:164-168','F09; SOL-002','await tx.user.updateMany(...); result.cashOuts = [];','Inject updateMany returning count=0. The transaction releases the seat and persists no unpaid cash-out, but credits nobody.','A player loses the complete remaining stack; an invariant violation becomes irreversible bookkeeping.','The cash-out loop never checks affected-row count.','Require exactly one authorized recipient per HUMAN cash-out; fail and roll back otherwise. Add a uniquely identified durable payout/ledger entry in the same locked transaction. Preserve bot issuance rules, row locks, revision checks and terminal closure.','Server node:test: missing, misclassified and duplicate recipients; then real Postgres rollback and concurrent retry.','Zero credited rows must leave the wallet, seat, state and payout obligation unchanged; valid cash-out and replay pay once.','Existing inconsistent rows need quarantine and reconciliation, not a blind replay of old payouts.',`${known}; expected rollback; actual released seat, zero credit, zero pending cash-outs.`,'known-backend.mjs');
add('Balances have no balanced, asset-specific financial ledger','S0','MONEY','The current single play-chip balance is unsuitable for redeemable value.','NEEDS-DECISION (assets, custody and accounting model)','apps/server/prisma/schema.prisma:63-83','F02; SOL-001; SOL-003; SOL-004','bankroll Int @default(10000)','Money is represented by mutable 32-bit bankroll/stack counters; no ledger accounts, posting pairs, asset identity, holds or reconciliation records exist.','Fiat and crypto cannot be reconciled or independently reconstructed; overflow would reject settlements and strand play.','A demonstration chip model is being considered for financial operation.','Design immutable double-entry postings per asset, integer minor units/atomic units, escrow table accounts and durable idempotency keys. Keep display amounts separate from database accounting and set explicit storage and aggregate limits.','Disposable Postgres: deposits, buy-ins, pots, cash-outs, reversals and withdrawal holds; assert zero-sum postings and reconstruct balances after crashes.','Every change has balanced entries, a unique business reference and an independent reconciliation trail; demo balances cannot become money.','Major schema and data migration; reconcile existing chips into a separate nonredeemable asset.',"rg -n 'bankroll|stack|model ' apps/server/prisma/schema.prisma; expected ledger/asset records; actual single Int counters.");
add('Instant chip grants have no hard boundary from future cash balances','S0','MONEY','10,000-chip grants are intentional demo issuance, and are readily farmable.','NEEDS-DECISION (strictly separate demo and cash modes)','apps/server/src/auth/routes.ts:96-102','F01; SOL-002; SOL-004','bankroll: env.DEFAULT_STARTING_BANKROLL','Both registration and anonymous guest creation grant positive bankroll. Config accepts only a positive starting grant; there is no cash mode, asset namespace or redemption boundary.','If these same chips become redeemable, account creation mints financial liabilities. This is conditional on a future cash launch, not a current cash exploit.','Account provisioning and economic issuance are coupled.','Separate demo and real accounts/assets. Real balance starts at zero and only an authorized funded ledger transaction credits it. Guest play must remain nonredeemable; bonuses need separate audited rules.','Auth plus ledger tests: zero real credit on register/guest, unlimited demo issuance cannot fund withdrawal or cash tables.','Cash APIs cannot consume demo balances; startup rejects an ambiguous money mode.','Changing default grants affects new users; existing demo balances must stay nonredeemable.',"rg -n 'DEFAULT_STARTING_BANKROLL|bankroll:' apps/server/src/auth/routes.ts apps/server/src/config.ts; both grant paths persist positive credit.");
add('No deposit, withdrawal or crypto custody system exists','S0','MISSING-CAPABILITY','Players can only acquire and play demonstration chips.','NEEDS-DECISION (licensed payments/custody provider and supported assets)','apps/server/src/app.ts:50-53','F03; SOL-002; SOL-005','app.use("/api/auth", ...); app.use("/api/tables", ...);','There are no money endpoints, signed webhook processing, chain confirmation/reorganisation handling, withdrawal approvals or custody key management.','A real-money service cannot accept, protect or return player funds with this implementation.','Payments and custody have not been implemented.','Use appropriately authorized providers with verified current scope for gambling and selected assets. Build signed/idempotent webhooks, confirmation and reorg policies, withdrawal holds, destination checks and reconciliation. Self-custody requires a separate reviewed security and operational programme.','Provider sandbox and disposable ledger: duplicate/reordered events, forged signatures, chargebacks, chain reorgs and failed withdrawals.','End-to-end funded deposit and withdrawal reconcile once; counsel and provider approve the actual market and custody arrangement.','Provider lock-in, compliance scope, payment fees and custody liability; no live migration or integration is authorized by this review.',"rg --files apps/server/src/routes apps/server/src/auth; inspect mounted endpoints above; expected financial workflow; none is implemented.");
add('Identity, age, geography and AML eligibility are not enforced','S0','LEGAL-EXPOSURE','Anonymous guests immediately play; public demo privacy and age policy also require review.','EXTERNAL (Malta gaming counsel, MLRO and identity/geolocation providers)','apps/server/src/auth/routes.ts:130-140','F04; SOL-004; SOL-007','res.status(201).json(await issueSession(user, req, res));','Guests obtain a session without age/identity confirmation; neither seating nor table creation evaluates verification, exclusions, market eligibility or AML state.','A proposed cash launch lacks core admission controls. Malta location alone does not authorize players worldwide. Verify the exact obligations with counsel.','The account/session and gameplay contracts have no authoritative eligibility state.','Define permitted markets and onboarding with counsel/MLRO. Enforce an eligibility decision server-side at cash access, seating, deposits and withdrawals, including sanctions/PEP and ongoing risk controls as required. Do not rely on a checkbox or client flags.','Server tests reject ineligible identities/markets even with valid JWTs; provider outages fail closed for cash access while preserving funds and due withdrawal handling.','Approved licence scope and market matrix, auditable decisions and independent bypass tests exist.','New personal data, provider dependencies and account migration require a privacy assessment.',"rg -n 'isGuest|role|kind|bankroll' apps/server/prisma/schema.prisma; trace guest issuance and manager.seatClaim; no eligibility gate is present.");
add('No responsible-gaming exclusion or limit enforcement exists','S0','LEGAL-EXPOSURE','No self-exclusion, limit-setting or published responsible-gaming flow is available.','EXTERNAL (gaming counsel and responsible-gaming lead)','apps/server/src/game/manager.ts:206-228','F05; SOL-005; SOL-007','async seatClaim(...); await tx.user.updateMany(...);','A valid session can keep playing without any self-exclusion, deposit/wager-limit or reality-check state; guests can create replacement identities.','Cash launch lacks required player-protection controls; verify applicable Malta requirements and timing with counsel.','Gameplay checks seat and balance eligibility only.','Implement identity-bound exclusion and mandatory tools, with enforceable limit changes/cooling-off rules and cross-tab/server consistency. Keep withdrawals and verified funds accessible under the approved exclusion policy.','Server and browser: exclusion while seated, across tabs/devices, a racing deposit/action, provider outage and attempted replacement accounts.','Limits and exclusions are enforced atomically at the relevant server boundaries; required player tools and support processes are usable.','House policy and new persistent compliance records are required.',"rg -n 'seatClaim|bankroll|requireAuth' apps/server/src/game/manager.ts apps/server/src/routes/tables.ts; no player-protection service or fields are used.");
add('Player terms, house rules, privacy and complaints flows are absent','S0','LEGAL-EXPOSURE','The public demo collects personal/session data without a visible privacy notice or published game policies.','EXTERNAL (gaming/data-protection counsel; owner approves house rules)','apps/web/src/app/layout.tsx:21-32','Claude lead 10; SOL-005; SOL-006; SOL-019; SOL-048','<AuthHydrator>{children}</AuthHydrator>','Only lobby, login and table routes exist. No terms/version acceptance, privacy/storage notice, age flow, complaints/dispute route or responsible-gaming information is linked.','Players cannot understand data processing or forced closures/disconnect rules; cash obligations must be verified with counsel before launch.','Legal and consumer-protection content was not integrated into onboarding or navigation.','Commission jurisdiction-specific documents and publish accessible links. Store required accepted document versions; disclose essential storage, retention, bots, timeouts and closure treatment. Add a usable complaints escalation flow.','Playwright: links before guest/account creation, accessible policy pages, required acceptance persistence and complaints submission; no dark patterns.','Counsel approves the actual flows and claims; all relevant pages are reachable on mobile and keyboard.','Legal content changes account flow and evidence retention; a cookie banner is not automatically necessary for strictly essential storage.',"rg --files apps/web/src/app; expected policy routes and acceptance flow; actual three page routes only.");
add('Recovery applies expired turns immediately after downtime','S1','FAIRNESS','A reconnecting player can be folded within milliseconds of recovery.','NEEDS-DECISION (interrupted-hand clock and recovery policy)','apps/server/src/game/manager.ts:109-126','F10; SOL-015; SOL-018','this.armTimers(table);','The saved turn deadline is retained across downtime. An expired saved turn schedules applyTimeout immediately; the existing probe observed TIMEOUT_FOLD after approximately 5 ms.','A restart/deploy can remove a player’s chance to act and change pot eligibility.','Turn recovery has no durable interruption/grace policy; idle recovery grace does not cover turns.','Choose pause/resume or a defined reconnection grace, persisted under the lock and shared across workers. Keep authoritative deadlines and stale-revision rejection; never silently replay a different deal.','Server fake-clock plus disposable Postgres crash/restart tests at each betting phase and showdown; browser reconnect sees the same new deadline.','A deploy cannot time out an interrupted turn before the documented grace; two workers agree on one deadline.','Players will notice clock changes; downtime treatment requires house-rule approval.',`${known}; expected a recoverable turn under a published policy; actual immediate TIMEOUT_FOLD.`,'known-backend.mjs');
add('Missing or undecryptable table state blocks every exit path','S1','RELIABILITY','A seated player cannot leave or cash out an affected table.','NEEDS-DECISION (audited operator recovery and adjudication policy)','apps/server/src/game/manager.ts:66-77','Claude lead 5; SOL-023; SOL-027','if (...) throw new EngineError("RECOVERY_REQUIRED", ...);','With missing encrypted state or invalid GCM data, manager.standUp fails; all mutations require load. Admin routes expose audits but no controlled repair/adjudication workflow.','Chips and the unique seat can be stranded indefinitely. No ordinary live corruption was found.','Fail-closed loading is correct, but no recovery capability resolves a quarantined financial obligation.','Freeze the affected table with an incident ID. Recover from verified durable state/history or adjudicate under an approved operator procedure with dual control and ledger reconciliation. Keep decryption and audit failures closed; never refund arbitrary stacks from untrusted rows.','Server corruption/missing-key tests plus disposable restoration exercise; unrelated tables remain playable and funds are accounted for exactly once.','A rehearsed, auditable recovery path exists for each corrupt/missing-state case without revealing hidden cards.','Recovery can change results; key restoration, reconciliation and operator access need approval.',`${faults}; expected a controlled resolution path; actual RECOVERY_REQUIRED/decryption rejection on leave.`,'server-faults.mjs');
add('The next shuffle can roll back completed-hand clean-up and payouts','S1','RELIABILITY','A departing player remains seated until the next deal can succeed.','CODE-NOW','apps/server/src/game/manager.ts:320-327','Claude lead 6; SOL-001; SOL-009','let next = completeHand(current); if (readyToDeal(next)) next = startHand(next);','Fault the RNG during the next start. The single transaction rolls back completeHand, retaining pendingLeave and its unpaid cash-out; the timer retries roughly every second.','An unrelated next-hand failure blocks already earned funds/seat release and creates a retry loop.','Clean-up and a fresh RNG-dependent deal share one transaction.','Commit verified completed-hand clean-up and cash-outs first. Start the next hand in a separate locked/revision-checked mutation with a bounded retry/incident policy. Keep RNG failure closed and hand persistence exactly once.','Server test faulting next-deal RNG/blind preconditions after a settled hand; assert cash-out committed once, no next-hand cards, then one new deal after recovery.','A failed fresh deal cannot undo a completed hand’s cash-outs; concurrent starts produce one hand.','Changes inter-hand orchestration; requires real-database race tests.',`${faults}; expected completed-hand payout survives next shuffle failure; actual ciphertext unchanged and pending leaver retained.`,'server-faults.mjs');
add('Database outages are treated as invalid sessions and destroy recovery','S1','RELIABILITY','A transient database timeout signs users out and disconnects sockets without automatic reconnection.','CODE-NOW','apps/server/src/auth/routes.ts:178-181','Claude lead 2; apps/server/src/auth/middleware.ts:19; apps/server/src/socket/index.ts:87-88; SOL-012; SOL-037','catch { clearRefreshCookie(res); res.status(401)... }','A fault in session lookup yields HTTP 401 and expires the refresh cookie. Per-packet authentication disconnects with io server disconnect; socket.io reports active=false. AuthHydrator clears valid local session on 401.','An infrastructure hiccup becomes permanent session loss mid-hand and can cost a turn.','Credential invalidity, revocation and dependency failure share a catch path.','Use typed invalid/expired/revoked versus unavailable errors. Return retryable 503 without deleting a valid cookie; pause authenticated sensitive delivery during outages, then retry with backoff. Preserve revocation enforcement.','Server fault injection for each auth endpoint/socket broadcast; Playwright resumes the same session after a temporary database outage.','Transient failures preserve credentials and recover; invalid/revoked tokens still fail closed.','Requires coordinated shared error contracts and careful privacy handling while auth is unavailable.',`${faults}; expected 503/preserved cookie/retry; actual 401, deleted cookie, server disconnect and active=false.`,'server-faults.mjs');
add('Access-token rotation resets the table during live play','S1','RELIABILITY','A genuine token change blanks legal controls while the socket rejoins.','CODE-NOW','apps/web/src/lib/socket.ts:13-15','Claude lead 1; apps/web/src/hooks/use-table-socket.ts:28-29; SOL-008; SOL-011; SOL-036','socket.disconnect(); ... io(...);','Change to a newly signed token and delay TABLE_JOIN by 1.5 seconds. Existing Call controls disappear until the new snapshot arrives. Ten-minute refreshes cause this during a 15-second turn.','Refresh, background throttling or packet loss can consume the acting window and leave action outcome ambiguous. The probe did not prove a lost committed action.','Token identity controls socket identity; the hook unconditionally resets trusted current table state.','Provide authenticated in-place reauthorization, or reconnect while retaining same-account verified state and an explicit reconnect overlay. Refresh based on expiry; recover action receipts before allowing resend. Clear private state on actual account switch/logout.','Playwright with genuinely different tokens, 1.5s/longer joins, expiry in a background tab and lost action acknowledgements.','Normal refresh preserves the visible verified hand; controls reflect connectivity; expiry resumes through the approved clock policy.','Security-sensitive lifecycle changes must not retain another account’s cards.',`${browser} --grep 'rotation'; expected continuous hand display; actual controls disappear during forced rejoin.`,'browser-defects.spec.ts');
add('Refresh rotation is not coordinated across browser tabs','S1','CONCURRENCY','One tab can receive a fatal 401 even while another refreshes successfully.','CODE-NOW','apps/server/src/auth/routes.ts:150-173','apps/web/src/lib/api.ts:39-50; apps/web/src/components/auth-hydrator.tsx:36-48; SOL-011; SOL-031','if (rotated.count !== 1) { res.status(401)... }','Two requests carrying the shared pre-rotation cookie return statuses [200,401]. The browser treats the loser’s 401 as terminal and clears that tab’s session. The refresh promise coordinates one JS realm only.','Ordinary multi-tab use can interrupt a hand without any invalid credentials.','Correct server CAS rotation has no cross-tab coordination or recoverable stale-rotation response.','Coordinate tabs with Web Locks/BroadcastChannel or an equivalent single-flight mechanism; distinguish stale rotation from revocation and retry once using the current cookie. Preserve single-use rotation and do not issue fresh tokens to arbitrary replay.','Server CAS race test and two real browser pages refresh simultaneously, then both remain signed in; revoked/stolen old cookies remain rejected.','Only one rotation occurs and honest tabs recover without logout or infinite refresh loops.','Browser support/fallbacks and replay semantics need deliberate design.',`${faults}; expected both honest tabs recover; actual refresh statuses 200 and 401. Client logout effect is traced in AuthHydrator.`,'server-faults.mjs');
add('Legacy bot scheduling can throw after commit and suppress delivery','S1','RELIABILITY','A committed state change can be reported as failed and left without a turn timer.','CODE-NOW','apps/server/src/game/manager.ts:182-194','Claude lead 11; apps/server/src/game/manager.ts:337-340; SOL-036','else this.armTimers(next); // before delivery Promise.allSettled','Inject a bot pacing RNG failure with manager timers enabled. mutate rejects after encrypted revision has committed; armTimers has removed the prior timer but has not installed the next one. Delivery code is never reached.','A legacy bot table can stall; acknowledgements lie about committed changes and wallet notifications can be skipped. Human-only new tables avoid the bot path.','Potentially throwing bot computation occurs synchronously outside post-commit error isolation.','Separate committed command outcome from scheduling/delivery. Catch and incident-report timer setup failures; retain a safe timeout/recovery timer. Consider worker offloading or retiring legacy bots; never substitute weak card randomness.','Server inject bot RNG/decision failure after commit; assert successful committed receipt, wallet notifications attempted and one safe recovery timer.','Post-commit scheduling cannot turn a committed command into a failure or block payout delivery.','Legacy behavior changes; worker offloading requires revision checks and bounded CPU.',`${faults}; expected committed result and recovery; actual rejected mutation, incremented persisted revision, no turn timer.`,'server-faults.mjs');
add('Restart grace for idle closure is process-local across workers','S1','CONCURRENCY','A newly resumed worker’s five-minute grace can be overridden by an older worker.','NEEDS-DECISION (rolling restart versus full-outage grace policy)','apps/server/src/game/manager.ts:357-365','apps/server/src/game/manager.ts:44; Claude lead 13; SOL-008','return Math.max(idleSince(table), this.resumedAt);','For one persisted idle table at a fixed time, a fresh manager would not warn while an older manager starts the warning. Redis shares rooms, not resumedAt or recovery generations.','Multi-worker deployments can close a table under inconsistent recovery promises; rolling starts can also cancel another worker’s warning.','Clock origin and stale-warning decisions are local process state.','Persist a table/server recovery generation and shared grace deadline under row lock, with documented rolling-restart semantics. Schedule using the persisted deadline and revision. Preserve terminal closure and exactly-once payouts.','Disposable Postgres plus two server processes: rolling restart, full outage, old warning and racing keep-alive/closure.','Both workers derive the same warning/closure deadline; stale callbacks cannot cancel or close a newer generation.','Requires migration and deployment coordination; the observed probe models two managers, not a real Redis cluster.',`${faults}; expected one shared restart grace; actual old worker warns when fresh worker would not.`,'server-faults.mjs');
add('An active idle warning is not replayed to reconnecting lobby users','S1','FAIRNESS','A lobby reload or token reconnect during a warning can hide the chance to keep the table.','CODE-NOW','apps/server/src/socket/index.ts:115-121','apps/server/src/game/manager.ts:261-275; SOL-012; SOL-015','socket.emit(SOCKET_EVENTS.AUTH_OK, { userId, username, activeTableId });','Start a warning before the lobby connects. AUTH_OK gives the seated table ID but no current TABLE_IDLE_NOTICE; the browser has no warning dialog. The notice is emitted only on transitions.','A seated player can miss the 10-second response window and be forced into closure/timeout treatment.','Authentication rehydrates the seat identity, not the current warning state.','On authenticated connection return the current authorized warning/closure status with generation and remaining deadline. Make client updates idempotent and clear obsolete generations; do not reintroduce lobby autojoin or unguarded table snapshots.','Server auth during an active warning; Playwright reload lobby/reconnect/rotate token at 3 seconds remaining and exercise keep-alive.','An active warning is visible immediately after reauthentication and cannot be overwritten by an old notice.','New shared payload contract; latency and expired notices require careful ordering.',`${faults} and ${browser} --grep 'warning'; expected current warning replay; actual activeTableId present, zero notices and no lobby alertdialog.`,'server-faults.mjs');
add('Optional sound/storage failures prevent a poker action from being sent','S1','RELIABILITY','A denied localStorage access leaves the action button permanently pending.','CODE-NOW','apps/web/src/components/table/action-bar.tsx:57-61','apps/web/src/lib/sounds.ts:7-16','setPending(true); playSound(...); try { ... }','Throw SecurityError from localStorage.getItem after the page loads and click Call. No ACTION_INTENT is emitted and the pending button stays disabled; audio construction can fail similarly.','A cosmetic preference can cost a turn and strand controls.','Sound is executed before the action’s try/finally and optional browser I/O is not isolated.','Make audio and preference storage best-effort, catching denied storage/unsupported audio. Put pending lifecycle in a guaranteed finally; poker commands must not depend on audio success.','Playwright with denied storage, absent AudioContext and throwing audio constructors; action still sent once and pending resets.','All legal actions remain usable with sound entirely unavailable; mount-time sound preference reads cannot crash controls.','Minimal UI change; preserve deliberate user-gesture audio rules.',`${browser} --grep 'sound'; expected action sent despite sound failure; actual zero ACTION_INTENT and disabled Call.`,'browser-defects.spec.ts');
add('The turn countdown trusts the player’s wall clock','S1','FAIRNESS','A device clock one hour ahead shows an empty clock while Call remains enabled.','CODE-NOW','apps/web/src/components/table/seat-hud.tsx:42-45','SOL-008; SOL-041; packages/shared/src/events.ts:146-150','snapshot.turnEndsAt - Date.now()','The turn bar derives its remaining time from an absolute server deadline minus the client wall clock instead of the snapshot’s relative remaining budget.','Players misjudge their acting window; devices behind the server may show time after the server has expired it.','Server and device epoch clocks are assumed equal.','Anchor remaining server time to performance.now(), adjusting for estimated delivery latency and resyncs. Show a textual deadline/remaining state and detect clock drift on servers. Keep server timeout authority.','Playwright synthetic wall clock +/-1 hour and background-tab resume, delayed snapshots and clock jumps.','Countdown tracks the server’s remaining budget within a stated latency tolerance regardless of device date settings.','Server clock discipline remains an operational requirement; no client countdown can guarantee network delivery time.',`${browser} --grep 'clock'; expected positive countdown; actual transform scaleX(0) while an action is available.`,'browser-defects.spec.ts');
add('Absent players keep paying future blinds without an explicit policy','S1','FAIRNESS','Repeated timeouts do not automatically sit an absent player out.','NEEDS-DECISION (disconnect, timeout and seat-reservation policy)','packages/engine/src/table.ts:323-329','apps/server/src/game/manager.ts:48-49; Claude lead 13; SOL-007','export function applyTimeout(...);','A two-player 30-hand probe times out one player 75 times; sittingOut remains false and their stack changes from 1,000 to 915. An active opponent keeps the table active, so table-wide idle closure does not protect the absent player.','A disconnected/lobby/background user can keep exposing chips in future hands indefinitely. This is an unpublished policy gap, not a demonstrated arithmetic bug.','Presence is not tracked for gameplay and timeout affects only the current action.','Approve and publish automatic sit-out thresholds and reconnect behavior. Apply any sit-out between hands under the lock; keep all-in hands eligible and respect missed-blind rules. Avoid one tab disconnect removing an account still active elsewhere.','Engine policy tests and multi-tab server/browser disconnect tests; live all-ins survive and future absent blinds stop at the published threshold.','Players can predict timeout/disconnection consequences; no unintended later deals occur after policy sit-out.','Material house-rule change; league/tournament and cash policies may differ.',`${policy}; expected defined absent-player protection; actual 30 hands, 75 timeouts, still sitting in and 915 chips remaining.`,'absence-and-config.mjs');
add('Game-integrity controls stop at legal actions and hidden-card isolation','S1','MISSING-CAPABILITY','Multiple accounts, collusion and external assistance are not detected.','NEEDS-DECISION (game-integrity operations, staffing and vendor)','apps/server/src/auth/routes.ts:130-140','F06; SOL-005; SOL-027','username: `Guest_${suffix}`','Any number of guests can play together. HUMAN is an account label, not evidence that a player is human or independent; no collusion, chip-dumping, RTA/bot or account-linking review system exists.','Adversaries can exploit honest players without breaking betting validation or cryptography.','No game-integrity programme is implemented.','Add authorized identity/device/risk signals, hand-pattern review, anti-collusion and chip-dumping detection with human case handling. Publish rules and appeals; do not promise that CAPTCHA alone proves fair play.','Synthetic labeled collusion/chip-dumping cases, false-positive checks and enforcement/appeal audit tests.','A staffed, measured detection-and-response process exists before cash play; privacy lawful basis is documented.','Detection errors can exclude honest users; thresholds and sanctions need policy and legal review.',"rg --files apps/server/src; inspect guest issuance and hand persistence; no integrity detection/case service is present.");
add('Account security lacks uniform login work and privileged MFA','S1','SECURITY','Login timing exposes account existence; no recovery or privileged step-up flow exists.','NEEDS-DECISION (account recovery and privileged-authentication model)','apps/server/src/auth/routes.ts:116-121','F07; apps/server/src/routes/admin.ts:41-44; SOL-024','if (!user?.passwordHash || user.kind === "BOT") ...; await bcrypt.compare(...)','Unknown users return before bcrypt; known password users perform the expensive check. Admin access relies on password/JWT plus database role, with no MFA/step-up or managed recovery flow.','Account enumeration and a stolen privileged session can expose full sealed decks; players cannot safely recover credentials. No ordinary auth bypass was found.','Account hardening and privileged identity controls are incomplete.','Perform a dummy bcrypt check for nonexistent users, uniform errors and account-aware throttling. Require strong managed MFA/step-up for privileged audit/key actions; design email verification and recoverable accounts without weakening session revocation.','Server timing/work-path tests and admin MFA expiry/revocation; recovery token single-use/rate-limit tests.','Unknown/known invalid logins follow equivalent expensive work; privileged operations require approved factors and logging.','Existing admins and players need enrollment; uniform errors change registration/login UX.',"rg -n 'bcrypt|passwordHash|ADMIN|authenticate' apps/server/src/auth/routes.ts apps/server/src/routes/admin.ts; code path shows differing work and no step-up.");
add('Malformed request bodies bypass limits and enter error logs','S1','PRIVACY','An invalid JSON password marker is logged and requests return 500.','CODE-NOW','apps/server/src/app.ts:39-58','F08; apps/server/src/routes/admin-access-log.ts:19-23','app.use(express.json(...)); ... logger.error({ err }, "request failed");','The parser runs before global/auth limits. Sixteen malformed requests bypass the auth limiter; parser errors log their body, including a synthetic password, and are incorrectly mapped to 500. Admin logs also retain arbitrary query strings via originalUrl.','Passwords/tokens supplied in invalid bodies or URLs can reach durable logs; malformed traffic evades controls.','Unfiltered error serialization and middleware ordering.','Apply appropriate pre-parser limits, map parser failures to 400/413, and log a safe error allow-list without body/credentials. Normalize admin route/path/query allow-lists; preserve every-request outcome logging.','Server malformed JSON containing synthetic secrets and query credentials; inspect captured logs and 400/413/429 outcomes.','No secret marker appears in logs; parser abuse is limited; admin denials remain auditable.','Logging schema changes affect incident tooling; redact before export, not only in a sink.',`${known}; expected 400 plus redaction and throttling; actual 500, synthetic password in log and parser-limit bypass.`,'known-backend.mjs');
add('Encrypted state has one unversioned environment key and no rotation path','S1','SECURITY','Loss of GAME_ENCRYPTION_KEY strands state and audits; rotation cannot be performed safely.','NEEDS-DECISION (KMS/HSM custody, rotation and recovery)','apps/server/src/game/encryption.ts:3-20','F11; apps/server/src/config.ts:19-21,49; SOL-009','const key = Buffer.from(env.GAME_ENCRYPTION_KEY, "hex"); ... `v1...`','AES-GCM uses one key for all live tables and sealed audits. The format has no key ID. Production checks accept an all-zero 32-byte AES key and reuse of that value as a JWT secret.','Compromise has broad scope; replacement makes old data unreadable. Entropy cannot be established by checking string length.','Key lifecycle, provenance and separation are not represented.','Use distinct managed encryption/signing keys and versioned envelope encryption with authenticated key IDs/contexts. Reject known placeholders/reuse, retain old decrypt keys through audited re-encryption and restoration drills. Keep random nonces and table/hand AAD.','Old/new key read/write, swapped key IDs, AAD mismatch, nonce uniqueness and staged rotation with disposable restored data.','A tested rotation/rollback/restore procedure exists; no production data becomes unreadable or plaintext.','Requires ciphertext format migration and secure key-retention policy; never log key material.',`${known}; expected rejection of synthetic zero/reused keys; actual production config accepts them.`,'known-backend.mjs');
add('Runtime database authority includes identity roles and credential hashes','S1','SECURITY','A compromised game process can read hashes and change roles/balances.','CODE-NOW','apps/server/prisma/migrations/20260920140611_poker_security/migration.sql:24-37','F12; apps/server/prisma/schema.prisma:68-73; SOL-021','GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE ... TO poker_server','Read-only live privilege checks return true for User UPDATE, role-column UPDATE and passwordHash SELECT. Hand UPDATE/DELETE and User DELETE are correctly denied.','Compromise of a broadly privileged runtime expands into identity takeover, privileged deck access and arbitrary wallet changes. This is not a public RLS bypass.','Table-level grants make identity and gameplay share one trust boundary.','Split identity/admin/wallet capabilities and restrict column grants or reviewed scoped procedures. Ordinary gameplay must not grant itself ADMIN or directly rewrite money. Keep server-only RLS and append-only hand restrictions.','Disposable roles: game role cannot change role/hash/ledger balance; permitted game operations still work, auth uses a narrower appropriate service.','Minimal grants are proved with actual role SQL, including all inherited privileges and deployment migrations.','Grant/service separation is a migration and architectural change; avoid locking out legitimate auth during cutover.',"node review/gpt-6.1-sol/repro/live-aggregates.mjs (explicit READ ONLY; approved network access); actual privilege booleans above.",'live-aggregates.mjs');
add('Encryption and operator-held hashes do not prevent valid snapshot replay','S1','DATA','A database/key insider can replay earlier valid encrypted state; complete deletion lacks an independent witness.','NEEDS-DECISION (independent audit/state anchoring)','apps/server/src/game/encryption.ts:14-19','F13; apps/server/src/game/manager.ts:66-74; COMPLIANCE.md:106-107; SOL-026','decipher.setAAD(Buffer.from(context)); return JSON.parse(...);','AAD binds a ciphertext to its table, not to an independently monotonic revision. Earlier valid ciphertext authenticates for that table. Operator-held chains cannot prove that the latest tail or every record was never deleted.','Privileged rollback or wholesale rewriting may change history/state without independent detection. Existing client live evidence helps only observers who retained it.','No durable witness outside the writable/operator-controlled trust boundary.','Anchor commitments, settlement heads and wallet postings to independently controlled append-only/WORM evidence; verify state revision against an authenticated monotonic record. Document exact threat limits and avoid claiming all modifications/deletions are detectable.','Replay an earlier valid state and remove an audit tail in a disposable store; independent checkpoint must flag it without exposing hidden cards.','Rollback/deletion is detected relative to a retained independent checkpoint and procedures resolve mismatches fail closed.','Anchoring incurs latency/cost and needs retention/availability design.',"rg -n 'setAAD|decryptState|revision|previousHandHash' apps/server/src/game/encryption.ts apps/server/src/game/manager.ts packages/shared/src/audit.ts; no independent freshness authority exists.");
add('Audit verification accepts a re-sealed illegal betting sequence','S1','FAIRNESS','Internal outcome verification is weaker than full rules replay; honest engine legality remains enforced.','CODE-NOW','packages/engine/src/audit.ts:64-144','F14; packages/shared/src/audit.ts:402-455; SOL-025','PLAYER_ACTION ... contributions ...','Rewrite a CALL of 10 to CHECK of 10 and recompute hashes. Both card-integrity and outcome verification return success although a check cannot pay 10.','A privileged forger can produce a self-consistent but illegal transcript accepted as an audited outcome. No ordinary client can bypass engine legality with this.','Replay validates arithmetic and settlement rather than authoritative turn/minimum-raise/action legality.','Build an independent deterministic rules replay from a complete initial-state contract; validate actor, phase, amounts, reopening, statuses and timeout reasons. Version transcripts/rules; retain card redaction and current semantic checks.','Jest/participant/server tests: re-sealed wrong actor, illegal check/call, undersized raise, reopening and phase-order forgeries; legitimate corpus still accepted.','All rule-invalid transcripts fail; all valid legacy/current audited versions behave under a documented compatibility policy.','Audit schema/history versioning may require migration; do not expose sealed cards to participant replay.',`${known}; expected illegal CHECK rejected; actual cardIntegrity=true, handOutcome=true.`,'known-backend.mjs');
add('Operational retention, restoration and financial incident procedures are unproved','S1','MISSING-CAPABILITY','Repository recovery cannot demonstrate deployment backup or support capability.','EXTERNAL (operator, SRE and privacy lead)','apps/server/src/index.ts:55-60','F22; apps/server/prisma/schema.prisma:86-98; SOL-009; SOL-023','await prisma.$disconnect(); process.exit(0);','No repository evidence proves tested encrypted backup restoration, payout reconciliation, retention/deletion schedules, on-call game incidents or privileged key/deck access monitoring. One expired live session remains; this alone is not a retention violation.','Failures can strand funds or personal data without a rehearsed resolution path. Actual external operations were not inspected.','Operational assurance and retention jobs/runbooks are outside the implemented application.','Publish runbooks and SLOs, validate draining and crash recovery, rehearse encrypted restores with required keys, and implement approved retention/data-rights workflows. Reconcile wallets and preserve required append-only evidence.','Disposable recovery drill with in-flight hands/payouts and restored keys; retention dry-run plus failure alerts.','Operator supplies executed drill, alert and retention evidence, with owners and escalation times.','Retention changes need counsel approval and may conflict with audit/AML preservation; no blind history deletion.',"rg --files; inspect shutdown, schema and deployment docs. No executed production restore or operational controls were supplied.");
add('Independent RNG, rules, security and production assurance are absent','S1','TEST-GAP','In-repository tests are extensive, but do not constitute independent certification.','EXTERNAL (accredited testing laboratory and penetration-test provider)','COMPLIANCE.md:105-112','SOL-005; SOL-026; SOL-027','Laboratory certification is still required.','No laboratory report, scoped penetration-test report, production inspection or approved game rules certificate was provided. The docs acknowledge this.','The highest online-poker assurance standard cannot be claimed from this code review or passing statistical samples.','Independent assurance/release approval has not been demonstrated.','After code/policy gates, commission the appropriate accredited assessment for the actual Malta/market deployment, RNG/game versions, custody boundaries and security configuration; track remediation to closure.','External test plans include game-rule corpus, hostile clients, insider/access boundary, financial fault tests and deployed infrastructure.','Evidence references the exact released build/config and all relevant critical/high issues are closed or formally resolved by the appropriate authority.','Cost and lead time; code, infrastructure or rules changes may require reassessment.',"Inspect COMPLIANCE.md sections 6.1 and 6.8; no certification evidence is delivered with the repository.");
add('Real database and multiple-process financial races remain unverified','S1','TEST-GAP','In-memory tests cannot prove production locks, deadlocks and constraints.','EXTERNAL (CI/SRE provisioning a disposable Postgres and Redis test environment)','apps/server/test/integration.test.mjs:1-24','Claude lead 3; SOL-001; SOL-010; SOL-015','POKER_INTEGRATION_TESTS ... DATABASE_TEST_ADMIN_URL','Docker/psql/disposable Postgres were unavailable. Existing integration tests require explicit opt-in; the normal passing server suite uses Prisma substitutes. No destructive live test was run.','One-seat and payout concurrency invariants lack executed real-database evidence in this review. No actual seat-claim double debit was demonstrated.','Required concurrency/fault CI gates are not part of the default evidence.','Provision an isolated database, apply both constraint/grant migrations, and run two independent server processes. Add real cross-table last-seat, create-versus-claim, timer-versus-action, restart and cash-out races. Keep the live database inaccessible to these tests.','node:test integration with real rollback, constraints, lock waits/deadlocks and process kills; verify total ledger funds and seat uniqueness.','Documented CI run passes against a disposable instance; the same tests fail when a required lock/constraint is intentionally removed.','Test fixtures must never reuse the repository-root live credentials.',"Get-Command docker,psql -ErrorAction SilentlyContinue; neither available; integration suite intentionally NOT RUN.");
add('Proxy TLS trust depends on an unverified network boundary','S2','CONFIG','Development is allowed to use HTTP; production proxy security depends on ingress isolation.','NEEDS-DECISION (ingress topology and application-port isolation)','apps/server/src/transport.ts:13-28','F15; apps/server/src/config.ts:40-48','X-Forwarded-Proto ... TRUST_PROXY_HOPS','With proxy trust enabled the secure-transport decision accepts the forwarded-proto header from the connecting peer. Direct access to the app port would permit a client to assert HTTPS. Production rediss and strict database TLS guards do exist.','A misconfigured deployment can bypass the intended transport gate. Actual public ingress was not probed.','Proxy hop count is configuration, not proof that the peer is the trusted proxy.','Restrict app ingress to the proxy, overwrite forwarded headers there, validate trusted peer addresses/topology and test every engine.io request. Publish a hardened deployment configuration; keep TLS guards and HSTS.','Staging network test: untrusted direct peer/header rejected; trusted proxy HTTPS works; HTTP polling and upgrades fail.','The application port is unreachable to clients and header spoofing cannot satisfy the production transport gate.','Topology changes affect health probes and rate-limit IP attribution.',"rg -n 'forwarded|proxy|secure' apps/server/src/transport.ts apps/server/src/config.ts; verify deployment firewall separately.");
add('Refresh sessions have no absolute lifetime or replay-family revocation','S2','SECURITY','A very old rotating session remains valid; replay rejection does not revoke its descendants.','NEEDS-DECISION (session lifetime and stolen-token response)','apps/server/src/auth/routes.ts:150-173','F16; SOL-013','expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)','The probe refreshes a session created 365 days earlier successfully. Reusing an old cookie returns 401, but the current access/session remains valid. Cookie/database expiry is hardcoded seven days while JWT_REFRESH_TTL is configurable.','Stolen-session exposure can persist and lifetime settings disagree; ordinary concurrent tabs must not be misclassified as attackers.','Only rolling expiry/current token hash is modeled, without family/absolute-age policy.','Define absolute session age, idle age, privileged sessions and replay response; store rotation/family evidence and distinguish legitimate concurrent refresh (SOL-013). Align cookie/JWT/database TTLs and support remote device revocation.','Server old-created session, replay family and configured TTL tests plus multi-tab refresh regression.','Approved absolute/idle limits are enforced consistently; replay and honest races have distinct safe outcomes.','Reauthentication affects long poker sessions; integrate the interrupted-turn policy.',`${known}; expected defined absolute cutoff; actual 365-day-old session refresh succeeds and replay leaves current access valid.`,'known-backend.mjs');
add('Revoked sockets still receive private wallet and idle notifications','S2','PRIVACY','Wallet changes can reach a revoked session until another authentication-triggering event removes it.','CODE-NOW','apps/server/src/game/manager.ts:245-247','F17; apps/server/src/game/manager.ts:275; SOL-011','this.io?.to(`user:${userId}`).emit(SOCKET_EVENTS.USER_PATCH, ...);','After the backing session is revoked, HTTP auth correctly rejects it but USER_PATCH still reaches the user room. TABLE_IDLE_NOTICE uses the same unconditional room delivery. Table/card broadcast does reauthenticate.','A logged-out or revoked device can learn bankroll/seat information. No hidden-card leak was observed on guarded snapshots.','Sensitive notification paths do not validate each receiving session or eagerly remove revoked sockets.','Route all private notifications through authorized per-socket delivery or reliable revocation-driven disconnection plus expiry checks. Preserve viewer-specific card projection and revalidate during dependency failures.','Server session deletion/expiry before each notification type; all devices/tabs stop receiving sensitive payloads, unrelated valid sessions still receive them.','Revocation stops private data on every channel, including account-room fan-out.','More auth checks may increase load; central revocation propagation must remain reliable across workers.',`${known}; expected revoked socket receives no wallet data; actual USER_PATCH contains the synthetic 10,000-chip balance.`,'known-backend.mjs');
add('Cookie-authenticated mutations have no explicit origin/CSRF validation','S2','SECURITY','A foreign-origin text/plain guest POST is accepted; no authenticated cross-site takeover was demonstrated.','CODE-NOW','apps/server/src/app.ts:33-40','F18; apps/server/src/auth/routes.ts:130-144; SOL-046','cors({ origin: env.CLIENT_ORIGIN, credentials: true })','CORS controls browser response access, not whether the route executes. The existing probe receives guest 201 from a foreign Origin with text/plain; production SameSite=Strict reduces cross-site authenticated cookie risk.','Login/session state can be changed or resources abused by unintended origins, especially same-site sibling origins or alternate deployments.','State-changing routes rely on CORS/cookie policy without request-origin/type checks.','Enforce allowed Origin/Referer or a tested CSRF token for cookie-authenticated mutations; require expected media types. Define non-browser API exceptions explicitly; preserve Strict cookies and exact socket-origin rules.','Server foreign/same-site sibling/null-Origin cases for guest/login/refresh/logout; legitimate first-party requests and approved API clients work.','Unapproved browser origins cannot perform session mutations even when cookies would be sent.','Origin checks affect tools/native clients; do not accidentally break health probes.',`${known}; expected foreign-origin mutation rejected; actual text/plain guest POST returns 201.`,'known-backend.mjs');
add('Sensitive auth responses have no explicit no-store policy','S2','PRIVACY','Auth/me/session responses omit Cache-Control; no actual intermediary leak was tested.','CODE-NOW','apps/server/src/auth/routes.ts:105-105','F19; apps/server/src/auth/routes.ts:140,174-177,203-204','res.status(201).json(await issueSession(...));','Guest/session responses include an access token and user details; /me includes personal data. Probe headers show Cache-Control absent. Audit routes correctly use no-store.','A future proxy/service worker/cache configuration may retain sensitive responses.','Auth router has no common response cache policy.','Set Cache-Control: no-store on all authenticated/token/session responses and appropriate Vary headers where needed. Verify CDN and service-worker rules do not override it. Retain existing audit-route policy.','Server checks each auth endpoint including errors; staging proxy tests verify no reusable auth objects.','All sensitive responses explicitly prohibit storage; public assets retain normal caching.','Small header change; may increase repeated auth network traffic.',`${known}; expected Cache-Control no-store; actual auth/me and guest headers are null.`,'known-backend.mjs');
add('Abuse limits and fan-out capacity are local and unmeasured','S2','RELIABILITY','Several tabs/replicas can multiply expensive work; busy shared IPs can exhaust global limits.','NEEDS-DECISION (capacity targets and distributed abuse control)','apps/server/src/app.ts:42-51','F20; apps/server/src/socket/rate-limit.ts:4-28; apps/server/src/game/manager.ts:290-301','rateLimit({ windowMs: 60_000, limit: 120 });','HTTP limits are process-local IP counters; socket budgets are per socket/process. Each viewer broadcast reauthenticates via database. Lobby polling consumes shared IP budget: eleven 5-second polling clients use about 132 requests/minute before other requests.','Load or adversarial connections can delay 15-second turns; replicas dilute limits while honest NAT users can receive 429. Actual production throughput is unmeasured.','No shared account/connection budget, fan-out backpressure or capacity evidence.','Use distributed per-account/IP/action controls with fair NAT allowances, connection/viewer caps, metrics and bounded fan-out. Benchmark real database latency, pool waits and bot CPU; keep authenticated private delivery.','Two-worker abuse tests, simulated shared NAT, spectator flood and sustained load with explicit latency/error SLOs.','Chosen load supports turn/payout deadlines; adding replicas does not multiply account limits or expose private data.','Limits can block honest players; Redis outages need a defined fail-closed/fair degradation strategy.',"rg -n 'rateLimit|setInterval|authenticate|Promise.all' apps/server/src/app.ts apps/server/src/socket/rate-limit.ts apps/server/src/game/manager.ts apps/web/src/app/page.tsx; load tests not run.");
add('Command IDs are not durable receipts and several commands lack acknowledgements','S2','CONCURRENCY','Lost replies leave outcomes ambiguous; stale revisions currently prevent ordinary double action.','CODE-NOW','apps/server/src/socket/index.ts:129-158','F21 (command delivery); Claude lead 4; packages/shared/src/events.ts:44,187-190; SOL-012; SOL-014','clientActionId: z.string().uuid(); ... socket.on(SEAT_CLAIM, (raw) => ...);','ACTION_INTENT validates a clientActionId but never stores/looks it up. Retrying a successful action after a lost acknowledgement yields stale state, not its prior result. SEAT_CLAIM/SIT_IN/SIT_OUT have no ack contract.','Players cannot reliably distinguish a failed request from committed action/seating; this is not a proved double debit because locks/revisions remain.','Transport request identity is not persisted as transaction outcome.','Persist bounded, authenticated command receipts keyed by user/session and command ID in the locked transaction. Return the same outcome on replay; add acknowledgements and reconciliation for all state-changing commands.','node:test and Playwright drop reply after commit, duplicate commands in two tabs and retry after reconnect; one mutation/credit and consistent outcome.','Every mutation has an unambiguous eventual result; receipts cannot be guessed/read across users or replayed as a different command.','Requires schema/retention migration and shared contracts; do not weaken stale-revision checks.',"rg -n 'clientActionId|ack|SEAT_CLAIM|SIT_IN|SIT_OUT' apps/server/src/socket/index.ts packages/shared/src/events.ts; ID is schema-only and these handlers omit acks.");
add('Health reports success even when gameplay dependencies are unavailable','S2','RELIABILITY','A load balancer cannot distinguish a live process from an unusable poker service.','CODE-NOW','apps/server/src/routes/health.ts:6-12','F21 (readiness); SOL-011; SOL-027','res.json({ ok: true, ... });','The health route returns 200/ok with a database connection that cannot succeed. Startup checks do not provide ongoing readiness or drain state.','Traffic can be routed to servers unable to authenticate, read or settle hands.','Liveness is exposed without a separate bounded readiness signal.','Keep lightweight liveness; add readiness for database/schema/key configuration and required fan-out dependencies, with timeout/cache and draining status. Never expose secrets or deep state in public health responses.','Server tests dependency down/recovered and draining; deployment exercises remove/add the worker at the correct points.','Ready=false/503 during dependency failure or drain; healthy startup becomes ready only after required checks.','Probe overload and flapping need hysteresis; maintain the permitted HTTP liveness exception.',`${known}; expected separate unhealthy readiness; actual health always reports 200/true.`,'known-backend.mjs');
add('Wallet updates can overwrite a newer balance with an older one','S2','UX','The screen can display 9,000 after 10,000 has already been delivered; database funds are unchanged.','CODE-NOW','apps/server/src/game/manager.ts:245-247','apps/web/src/app/page.tsx:30-35; packages/shared/src/events.ts:165-172; SOL-002','findUnique(... bankroll ...); ... emit(USER_PATCH, ...);','Delay the first wallet read/delivery and finish a newer read first: payloads arrive [10000,9000]. The lobby’s auxiliary /me fetch also patches without a wallet-version guard. Both were reproduced.','Bankroll display and affordable buy-in choices become stale after cash-out or another tab’s activity.','Wallet events have no persisted monotonic revision; some client fetch paths bypass the local anti-stale guard.','Add wallet revision to transaction/API/events and reject older revisions everywhere. Preserve existing refresh and on-connect walletVersion guards until the durable contract replaces them.','Server reversed delivery order plus Playwright delayed lobby /me and cash-out; newest balance wins, no synthetic extra credit.','All wallet sources are monotonic within one account; account switching resets safely.','Revision field/backfill is a migration; old clients need compatibility handling.',`${faults} and ${browser} --grep 'wallet'; expected newest 10000 retained; actual final displayed 9000.`,'server-faults.mjs');
add('The Next.js origin supplies no framing or content security policy','S2','SECURITY','Local web responses lack CSP and X-Frame-Options; a deployed proxy was not inspected.','CODE-NOW','apps/web/next.config.ts:4-14','apps/server/src/app.ts:23; SOL-007','const nextConfig: NextConfig = { ... };','API Helmet runs on the API origin. The separate Next origin has no headers configuration; browser probes find neither Content-Security-Policy nor X-Frame-Options.','Clickjacking is not prevented by app-provided web headers, and XSS lacks a policy containment layer. No working XSS injection was found.','Security headers cover only the backend origin.','Add production framing denial/frame-ancestors and a measured CSP with per-response nonce or supported hashes, exact websocket/API/font sources and a staged report-only rollout. Keep development needs separate and verify the deployed edge.','Playwright response/header and malicious-frame tests; test login, sockets, styles and hydration under the enforcing production CSP.','Actual web responses deny unauthorized framing and enforce the approved CSP without breaking gameplay.','CSP can break Next hydration/fonts or websocket transport if configured carelessly.',`${browser} --grep 'headers'; expected web-origin policy; actual both CSP and X-Frame-Options absent.`,'browser-defects.spec.ts');
add('Case-sensitive and reserved usernames enable identity confusion','S2','SECURITY','Alice/alice and guest-like registered names can coexist; this is not password-account takeover.','NEEDS-DECISION (canonical names and reserved/disclosed account identities)','apps/server/src/auth/routes.ts:15-19','Claude lead 7; apps/server/prisma/schema.prisma:67; SOL-020; SOL-050','regex(/^[a-zA-Z0-9_]+$/); username String @unique','Registration permits Guest_1a2b3c and case variants; PostgreSQL ordinary unique text compares case sensitively. Players see usernames without an immutable identity/verified-kind badge.','Impersonation and confusion assist collusion, disputes and support errors.','Display name, login identity and generated role naming share an unnormalized namespace.','Approve case-folding/reserved prefixes and stable identity display; store a canonical unique identifier and clearly distinguish guest/legacy bot/verified roles. Resolve existing collisions explicitly without merging accounts/funds.','Server case-variant/reserved-name registration and migration collision fixtures; UI shows approved identity markers.','Names follow one documented policy and cannot impersonate system roles; login/recovery respects canonical identity.','Requires a collision-aware migration and user rename notices.',"rg -n 'username|Guest_' apps/server/src/auth/routes.ts apps/server/prisma/schema.prisma; ordinary uniqueness is case-sensitive and no reserved-name check exists.");
add('Reduced-motion styling collapses the meaningful turn clock','S2','A11Y','The time bank immediately appears exhausted with reduced motion enabled.','CODE-NOW','apps/web/src/app/globals.css:222-223','apps/web/src/components/table/seat-hud.tsx:95-101; SOL-018','* { animation-duration: .01ms !important; }','The semantic timebank-drain animation is included in the blanket .01ms rule. Corrected browser diagnostics observed a finished 0.01ms animation with scaleX(0) initially and 1.2 seconds later while a turn was active.','Reduced-motion users lose visible time information, potentially misjudging a turn.','A timing indicator is treated as decorative motion.','Provide a nonanimated textual/stepped remaining-time indicator under reduced motion; separate decorative transitions from semantic deadlines. Keep server-authoritative time and accessible names.','Playwright emulate reduced motion after styles settle; assert readable positive remaining budget during an active turn and correct expiry.','Reduced-motion users receive the same deadline information without unnecessary movement.','CSS changes must preserve clock behavior for ordinary users; first exploratory sample raced media/style application.',`${browser} --grep 'reduced'; diagnostic duration 0.00001s and final scaleX(0). Source establishes the blanket rule; do not treat this diagnostic-only test as a comprehensive a11y assertion.`,'browser-defects.spec.ts');
add('Call-button text contrast is below WCAG AA for normal text','S2','A11Y','The enabled Call button measures approximately 3.19:1 instead of 4.5:1.','CODE-NOW','apps/web/src/components/table/action-bar.tsx:103-109','SOL-043; legal exposure register','bg-emerald-600 text-white','Browser computed colors yield contrast 3.1858692567863036 for 16px, font-weight 400 Call text. This is normal, not large text.','Low-vision players have difficulty reading a consequential action.','The button palette was not checked against its actual text size/background.','Choose colors giving at least 4.5:1 for normal action text; verify every state/background and focus indicator. Keep labels and button semantics.','Playwright computed-color checks plus manual high-contrast/zoom review; include hover/disabled treatment without relying on color alone.','Enabled consequential controls meet WCAG 2.2 contrast criteria; document exemptions only where applicable.','Minor visual palette change; legal applicability still requires counsel review.',`${browser} --grep 'contrast'; expected >=4.5; actual 3.1858692567863036.`,'browser-defects.spec.ts');
add('Turn ownership and remaining time are not announced accessibly','S2','A11Y','A check can move the actor without an announced phase or pot change.','CODE-NOW','apps/web/src/components/table/poker-felt.tsx:27-36','apps/web/src/components/table/action-bar.tsx:83; apps/web/src/components/table/seat-hud.tsx:95-101; SOL-018; SOL-042','aria-live="polite" ... phase/pot ...','The live status covers phase/pot/result, but actor changes at constant phase/pot are primarily visual. The time bank has no accessible remaining-time value, and Your turn is not a dedicated announcement.','Screen-reader users may miss a short acting opportunity. No assistive-technology session was executed.','Accessible status does not model the game’s turn/deadline state.','Add deduplicated, account-specific turn announcements with coarse remaining-time warnings and a readable timer. Avoid flooding live regions every frame; preserve card/seat/action names and dialog focus management.','Playwright accessibility snapshots for actor-only CHECK transitions, then manual NVDA/VoiceOver keyboard play.','A user can identify whose turn it is and their deadline without sight, with no announcement storm.','Announcement timing should be tested with real assistive technology.',"rg -n 'aria-live|Your turn|timebank' apps/web/src/components/table/poker-felt.tsx apps/web/src/components/table/action-bar.tsx apps/web/src/components/table/seat-hud.tsx; actor/deadline changes lack dedicated status.");
add('Joining a seat silently chooses the buy-in for the player','S2','UX','Clicking Sit here can move the entire available bankroll up to approximately 100 big blinds.','NEEDS-DECISION (join buy-in selection and confirmation)','apps/web/src/app/table/[id]/page.tsx:59-60','Claude lead 12; apps/web/src/app/table/[id]/page.tsx:81-84; apps/web/src/components/table/seat-hud.tsx:37-39','Math.min(snapshot.maxBuyIn, bankroll, Math.max(snapshot.minBuyIn, snapshot.bigBlind * 100))','The joiner has no amount selector or disclosed amount on the seat button. Creation supports custom buy-in and both server/engine correctly enforce 20–200 BB.','A player cannot choose how much to expose at the table and may commit more than intended.','Seat claim derives an amount from default UI state without confirmation.','Show an explicit buy-in selector/confirmation with min/max, available balance and exact resulting wallet; default 100 BB only as an editable suggestion. Keep authoritative server bounds and atomic debit.','Playwright low bankroll, custom blinds, decimal input and changing wallet; no debit until explicit amount confirmation.','The amount is visible and accepted before seating; server still rejects stale/invalid balances.','Changes one-click joining; owner must approve the intended user flow.',"rg -n 'defaultBuyIn|buyIn:|Sit here' 'apps/web/src/app/table/[id]/page.tsx' apps/web/src/components/table/seat-hud.tsx; fixed derived amount is sent without a selector.");
add('A fresh closed-table visit cannot reach its participant audit in the UI','S2','UX','Reloading an already closed table removes the Verify hand entry point.','CODE-NOW','apps/web/src/components/table/idle-close-dialog.tsx:346-351','apps/web/src/components/table/idle-close-dialog.tsx:407-416; apps/web/src/hooks/use-table-socket.ts:28-29; SOL-007','if (!snapshot) ...; snapshot && ... <FairnessAudit ...>','Load a closed table with finalHandNumber=1 in a fresh page. Join is correctly refused and no previous snapshot exists, so the closed dialog has no Verify hand control. The participant API remains available when the user was dealt in.','Players lose convenient evidence/dispute access after navigation or refresh.','Audit navigation depends on retaining the last live snapshot rather than a durable participant hand list.','Add authenticated participant-owned history/listing and route-independent audit navigation, including closed tables. Preserve participant authorization and do not reopen or publicly expose closed private tables.','Playwright closure then fresh reload/new tab; participant can verify permitted final hand, outsider cannot discover private history.','Completed participant audits remain reachable through UI after closure/logout-login without live state.','New read API/indexing and privacy boundary require tests.',`${browser} --grep 'closed'; expected audit entry point for prior participant; actual no Verify hand on fresh closed-table page.`,'browser-defects.spec.ts');
add('Production cookie policy requires a same-site deployment that is not enforced','S2','CONFIG','Default unrelated hosting domains can make session refresh fail in production.','NEEDS-DECISION (same-site web/API domains or a backend-for-frontend)','apps/server/src/auth/routes.ts:40-46','apps/server/src/config.ts:16; apps/web/src/lib/api.ts:22-27; SOL-033','sameSite: isProd ? "strict" : "lax"','CLIENT_ORIGIN permits any HTTPS origin. A web domain and API on unrelated registrable domains are cross-site, so Strict refresh cookies are not sent by credentialed browser fetch. This topology was not executed.','Login may initially work via access token, then refresh/sign-in restoration fails.','Allowed CORS origin and required cookie site topology are not validated/documented as one deployment contract.','Prefer HTTPS app/api under the same registrable domain or a same-origin BFF. Validate/document the chosen topology. If cross-site is essential, design CSRF defenses and third-party-cookie constraints before changing cookie policy.','Production-mode browser run on representative test hostnames/scheme; login, refresh, reload, logout and hostile origins.','Approved deployment supports cookies reliably and passes Origin/CSRF tests; Strict is not removed merely to make a default hosting URL work.','Domain/TLS/proxy changes; third-party-cookie support varies by browser.',"rg -n 'sameSite|CLIENT_ORIGIN|credentials' apps/server/src/auth/routes.ts apps/server/src/config.ts apps/web/src/lib/api.ts; compare actual hostnames before deployment.");
add('Startup accepts unusable bankroll, timer and JWT lifetime settings','S2','CONFIG','An allowed configuration can make accounts fail or turns expire immediately.','CODE-NOW','apps/server/src/config.ts:23-26','apps/server/src/game/manager.ts:352; SOL-002; SOL-031','JWT_ACCESS_TTL: z.string(); TURN_TIME_BANK_MS: ...positive();','The probe accepts starting bankroll and time bank of 2,147,483,648, beyond Postgres Int/Node timeout range, and JWT_ACCESS_TTL=not-a-duration. Node overlarge setTimeout delays clamp to a short delay; JWT issuance validates too late.','Configuration errors can disable registration or cause premature timeouts; default settings do not exhibit the overflow.','Format/positivity validation lacks operational bounds and parsed duration constraints.','Bound port/time/money values to safe storage/Node scheduling limits, parse JWT durations at startup and derive refresh scheduling from expiry. For future large timers, schedule bounded chunks against authoritative deadlines.','Server config child-process tests for boundaries and malformed TTLs; no DB connection required.','All unusable combinations fail startup with a safe message; valid expiry/clock settings match the client contract.','Tightening settings may reject existing deployments; provide migration/release notes.',`${policy}; expected invalid configuration rejected; actual all three accepted. Delay-clamping consequence is platform semantics/code inference, not a live financial test.`,'absence-and-config.mjs');
add('Play chips are labeled as dollars without clear nonredeemable disclosure','S2','DOCS-CLAIMS','Bankroll, pots and actions display dollar symbols even though no money service exists.','NEEDS-DECISION (demo units, currencies and redemption disclosure)','apps/web/src/app/page.tsx:144-144','Claude lead 8; apps/web/src/components/table/action-bar.tsx:106; SOL-003; SOL-007','${user.bankroll.toLocaleString()}','The lobby shows $bankroll, Need at least $1,000, and table controls use dollar amounts; visible gameplay does not consistently identify nonredeemable play chips or an actual fiat/crypto asset.','Players can infer a monetary balance or payout capability that the product does not provide. Verify consumer-facing claims with counsel.','Presentation units are hardcoded as money while accounting is demo chips.','Use explicit Play chips/nonredeemable wording and neutral chip units today. Later render the actual approved asset and precision from the ledger; disclose exchange/fee rules instead of silently substituting $.','Playwright checks lobby, actions, closure notices and audit displays for approved demo/asset units.','A first-time user can identify the balance’s asset and redemption status everywhere.','Copy/format change; multi-asset precision and locale formatting require shared display contracts.',"rg -n '\\$|bankroll|chips' apps/web/src/app/page.tsx apps/web/src/components/table/action-bar.tsx; current copy uses dollars for demo balances.");
add('Decimal bet input remains enabled and sends a rejected amount','S3','UX','Typing 20.5 produces an enabled action that the engine correctly rejects.','CODE-NOW','apps/web/src/components/table/action-bar.tsx:41-42','Claude lead 8; apps/web/src/components/table/action-bar.tsx:127-137','Math.min(max, Math.max(min, amount)); Number(e.target.value)','The numeric input can hold a decimal; clamping preserves it while the slider rounds separately. Clicking sends 20.5 and returns Amount must be a positive whole number. Empty/non-numeric input is normalized/clamped and does not bypass server validation.','A wasted click and confusing error; server funds remain protected.','Client amount state validates bounds but not integer finiteness consistently.','Validate one finite integer amount model for input, slider and shortcuts. Show the invalid state/disable submit or explicitly normalize before sending; preserve server integer and min/max checks.','Playwright decimal, empty, NaN/non-numeric, out-of-range and all-in/raise-to cases; no invalid intent emitted.','Input, slider label and sent amount agree; valid integer amounts still work.','Small input behavior change; do not silently round a financial amount without clear feedback.',`${browser} --grep 'decimal'; expected invalid input cannot submit; actual 20.5 emitted and rejected.`,'browser-defects.spec.ts');
add('Unique-account races and small guest suffix collisions surface as 500','S3','RELIABILITY','A legitimate registration race/guest collision receives a generic server failure.','CODE-NOW','apps/server/src/auth/routes.ts:89-105','Claude lead 7; apps/server/src/auth/routes.ts:131-140; SOL-040','const existing = await prisma.user.findFirst(...); ... user.create(...);','Two registrations can pass the pre-check before the database unique constraint wins. Guest names use only six hex characters (24 bits) without retry; injected Prisma P2002 returns HTTP 500.','Account creation fails intermittently as usage grows; no duplicate account or balance violation was shown.','Database uniqueness errors are neither classified nor recovered on the generated-name path.','Map known registration uniqueness conflicts to a controlled response, consistent with enumeration policy. Use a much larger guest namespace and bounded retry for that specific constraint. Leave other database failures retryable/observable.','node:test simultaneous register and forced guest P2002 collisions; no duplicate identity, bounded retries and sanitized logs.','Expected collisions return a stable user-facing result without 500; provider/database outages are not masked as collisions.','Guest naming/display change; handle old names without renaming funds.',`${faults}; expected bounded retry/controlled conflict; actual guest P2002 becomes HTTP 500. Registration race follows the same uncaught code path.`,'server-faults.mjs');
add('Metadata and tooling guidance advertise outdated product/deployment behavior','S3','DOCS-CLAIMS','Search/social metadata advertises AI opponents although new tables are human-only.','CODE-NOW','apps/web/src/app/layout.tsx:19-19','Claude lead 9; package.json:5; .cursor/rules/supabase.mdc:10; SOL-030','description: "Real-time Texas Hold\'em with autonomous AI opponents"','Page/root-package descriptions advertise AI opponents. Cursor guidance describes the target as local Docker, while explicitly read-only inspection reaches live Supabase. Legacy bots are separately disclosed in the lobby and seed remains a local bot fixture.','Players are misled about who they play; contributors can misunderstand the live-data boundary.','Documentation/metadata were not updated with the human-only and live database changes.','Update current metadata and operational guidance to the actual human-only demo/live database setup. Label historical milestones and local seed behavior clearly; keep explicit live-data safeguards.','Static copy inventory plus Playwright metadata/lobby comparison; documented local commands use an explicitly disposable database.','Current guidance matches implemented behavior and warns accurately that root .env targets live data.','Copy-only change; keep historical dated records distinct from current requirements.',"rg -n 'AI|bots|local|Docker' apps/web/src/app/layout.tsx package.json .cursor/rules/supabase.mdc; compare human-tables tests and read-only live evidence.");
